</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
  '[{"value":"2,50 %","label":"Taux directeur Banque du Canada"},{"value":"3,1 %","label":"IPC global de septembre"},{"value":"1,8 %","label":"IPC-tronq de septembre"},{"value":"9 déc.","label":"Prochaine décision de la Banque"}]',
