  xl.forEach(function(s, i){
    if (s === "") return;
    svg.appendChild(el("text", {x: xp(i), y: margin.top + PH + 14, "text-anchor": i === n - 1 ? "end" : "middle", "font-size": 8, fill: "#999999", "font-family": FONT}, s));
  });
  // band label, in the top margin above the band
  svg.appendChild(el("text", {x: (bx0 + bx1) / 2, y: margin.top - 5, "text-anchor": "middle", "font-size": 7, "font-weight": 700, fill: "#c0392b", "font-family": FONT}, "SEPT SÉANCES : +" + "12,0" + " %"));
  // reference label below its line, centred on a clear stretch (Oct 12 to Oct 21)
  var refX = (xp(17) + xp(24)) / 2;
  svg.appendChild(el("text", {x: refX, y: refY + 12, "text-anchor": "middle", "font-size": 7, "font-weight": 700, fill: "#7a3030", "font-family": FONT}, "100 $ US/BARIL"));
